// fifo_sequence: base, reset, fill, drain, write-when-full and random stress sequences.

class fifo_base_sequence extends uvm_sequence #(fifo_seq_item);

  `uvm_object_utils(fifo_base_sequence)

  // Items generated by body()
  int num_transactions = 100;

  function new(string name = "fifo_base_sequence");
    super.new(name);
  endfunction : new

  virtual task body();
    `uvm_info(get_type_name(), $sformatf("Starting sequence execution with %0d transactions...", num_transactions), UVM_MEDIUM)

    repeat (num_transactions) begin
      req = fifo_seq_item::type_id::create("req");

      start_item(req);

      if (!req.randomize()) begin
        `uvm_fatal("RND_FAIL", "Randomization failed in fifo_base_sequence!")
      end

      finish_item(req);
    end

    `uvm_info(get_type_name(), "Completed sequence execution.", UVM_MEDIUM)
  endtask : body

endclass : fifo_base_sequence

// 5 idle items after reset.
class fifo_reset_sequence extends fifo_base_sequence;

  `uvm_object_utils(fifo_reset_sequence)

  function new(string name = "fifo_reset_sequence");
    super.new(name);
    num_transactions = 5;
  endfunction : new

  virtual task body();
    `uvm_info(get_type_name(), "Starting fifo_reset_sequence (5 idle transactions)...", UVM_MEDIUM)

    repeat (num_transactions) begin
      req = fifo_seq_item::type_id::create("req");
      start_item(req);

      if (!req.randomize() with {
        wr_en   == 1'b0;
        rd_en   == 1'b0;
        data_in == 8'h00;
      }) begin
        `uvm_fatal("RND_FAIL", "Randomization failed in fifo_reset_sequence!")
      end

      finish_item(req);
    end

    `uvm_info(get_type_name(), "Completed fifo_reset_sequence.", UVM_MEDIUM)
  endtask : body

endclass : fifo_reset_sequence

// 32 writes with data 0 to 31.
class fifo_fill_sequence extends fifo_base_sequence;

  `uvm_object_utils(fifo_fill_sequence)

  function new(string name = "fifo_fill_sequence");
    super.new(name);
    num_transactions = 32;
  endfunction : new

  virtual task body();
    `uvm_info(get_type_name(), "Starting fifo_fill_sequence (32 writes with incrementing data)...", UVM_MEDIUM)

    for (int i = 0; i < 32; i++) begin
      req = fifo_seq_item::type_id::create("req");
      start_item(req);

      if (!req.randomize() with {
        wr_en   == 1'b1;
        rd_en   == 1'b0;
        data_in == i[7:0];
      }) begin
        `uvm_fatal("RND_FAIL", $sformatf("Randomization failed in fifo_fill_sequence at write index %0d!", i))
      end

      finish_item(req);
    end

    `uvm_info(get_type_name(), "Completed fifo_fill_sequence.", UVM_MEDIUM)
  endtask : body

endclass : fifo_fill_sequence

// 32 reads.
class fifo_drain_sequence extends fifo_base_sequence;

  `uvm_object_utils(fifo_drain_sequence)

  function new(string name = "fifo_drain_sequence");
    super.new(name);
    num_transactions = 32;
  endfunction : new

  virtual task body();
    `uvm_info(get_type_name(), "Starting fifo_drain_sequence (32 consecutive reads)...", UVM_MEDIUM)

    for (int i = 0; i < 32; i++) begin
      req = fifo_seq_item::type_id::create("req");
      start_item(req);

      if (!req.randomize() with {
        wr_en == 1'b0;
        rd_en == 1'b1;
      }) begin
        `uvm_fatal("RND_FAIL", $sformatf("Randomization failed in fifo_drain_sequence at read index %0d!", i))
      end

      finish_item(req);
    end

    `uvm_info(get_type_name(), "Completed fifo_drain_sequence.", UVM_MEDIUM)
  endtask : body

endclass : fifo_drain_sequence

// Fill, 3 writes of 0xFF while full, then drain.
class fifo_write_when_full_sequence extends fifo_base_sequence;

  `uvm_object_utils(fifo_write_when_full_sequence)

  function new(string name = "fifo_write_when_full_sequence");
    super.new(name);
  endfunction : new

  virtual task body();
    `uvm_info(get_type_name(), "Starting fifo_write_when_full_sequence...", UVM_MEDIUM)

    // Fill: data 0 to 31
    `uvm_info(get_type_name(), "Step 1: Filling FIFO with 32 writes...", UVM_HIGH)
    for (int i = 0; i < 32; i++) begin
      req = fifo_seq_item::type_id::create("req");
      start_item(req);
      if (!req.randomize() with {
        wr_en   == 1'b1;
        rd_en   == 1'b0;
        data_in == i[7:0];
      }) begin
        `uvm_fatal("RND_FAIL", $sformatf("Randomization failed during Step 1 (fill index %0d)!", i))
      end
      finish_item(req);
    end

    // Overflow: 3 writes of 0xFF while full, must be ignored
    `uvm_info(get_type_name(), "Step 2: Attempting 3 illegal writes while FIFO is full (expecting DUT to ignore)...", UVM_HIGH)
    for (int j = 0; j < 3; j++) begin
      req = fifo_seq_item::type_id::create("req");
      start_item(req);
      if (!req.randomize() with {
        wr_en   == 1'b1;
        rd_en   == 1'b0;
        data_in == 8'hFF;
      }) begin
        `uvm_fatal("RND_FAIL", $sformatf("Randomization failed during Step 2 (overflow index %0d)!", j))
      end
      finish_item(req);
    end

    // Drain: must read back 0 to 31
    `uvm_info(get_type_name(), "Step 3: Draining 32 items to verify data integrity...", UVM_HIGH)
    for (int k = 0; k < 32; k++) begin
      req = fifo_seq_item::type_id::create("req");
      start_item(req);
      if (!req.randomize() with {
        wr_en == 1'b0;
        rd_en == 1'b1;
      }) begin
        `uvm_fatal("RND_FAIL", $sformatf("Randomization failed during Step 3 (drain index %0d)!", k))
      end
      finish_item(req);
    end

    `uvm_info(get_type_name(), "Completed fifo_write_when_full_sequence.", UVM_MEDIUM)
  endtask : body

endclass : fifo_write_when_full_sequence

// 2000 random items with the default constraints.
class fifo_random_stress_sequence extends fifo_base_sequence;

  `uvm_object_utils(fifo_random_stress_sequence)

  function new(string name = "fifo_random_stress_sequence");
    super.new(name);
    num_transactions = 2000;
  endfunction : new

  virtual task body();
    `uvm_info(get_type_name(), $sformatf("Starting fifo_random_stress_sequence with %0d transactions...", num_transactions), UVM_LOW)

    super.body();

    `uvm_info(get_type_name(), "Completed fifo_random_stress_sequence.", UVM_LOW)
  endtask : body

endclass : fifo_random_stress_sequence
